import * as fs from 'node:fs';
import * as path from 'node:path';

// Taikyokudraft piece sets (assets/taikyokudraft/<set>/{0,1}_<ROLE>.svg, generated by
// bin/taikyoku-pieces/gen-svgs.py in the style of chushogi/ryoko_1kanji).
//
// Selectors follow chushogi.ts / standard.ts: "0_" faces up (own pieces, bottom hand, bottom spare),
// "1_" faces down. Unlike the other variants the images are NOT inlined as base64: with 350 roles
// that would be a ~5 MB stylesheet, while a game only ever shows a dozen of them. The css references
// the svg files (copied to public/piece/taikyokudraft/<set>/), so the browser fetches what is on screen.

function classes(up: boolean, role: string): string {
  const V = '.v-taikyokudraft';
  return up
    ? [
        `${V} .sg-wrap.orientation-sente piece.${role}.sente`,
        `${V} .sg-wrap.orientation-gote piece.${role}.gote`,
        `${V} .hand-bottom piece.${role}`,
        `.spare-bottom.v-taikyokudraft piece.${role}`,
      ].join(',\n')
    : [
        `${V} .sg-wrap.orientation-sente piece.${role}.gote`,
        `${V} .sg-wrap.orientation-gote piece.${role}.sente`,
        `${V} .hand-top piece.${role}`,
        `.spare-top.v-taikyokudraft piece.${role}`,
      ].join(',\n');
}

export function taikyokudraft(sourceDir: string, cssDestDir: string, imgDestDir: string): void {
  if (!fs.existsSync(sourceDir)) return;
  fs.mkdirSync(cssDestDir, { recursive: true });
  for (const set of fs.readdirSync(sourceDir)) {
    const setDir = path.join(sourceDir, set);
    if (!fs.statSync(setDir).isDirectory()) continue;
    const files = fs.readdirSync(setDir).filter(f => f.endsWith('.svg'));
    const roles = files
      .filter(f => f.startsWith('0_'))
      .map(f => f.slice(2, -4))
      .sort();
    const imgDir = path.join(imgDestDir, set);
    fs.mkdirSync(imgDir, { recursive: true });
    for (const f of files) fs.copyFileSync(path.join(setDir, f), path.join(imgDir, f));
    const url = (file: string) => `url('../../piece/taikyokudraft/${set}/${file}')`;
    const css = [
      '.v-taikyokudraft piece { will-change: auto; background-repeat: no-repeat; }',
      ...roles.flatMap(R => {
        const role = R.toLowerCase();
        return [
          `${classes(true, role)} {background-image:${url(`0_${R}.svg`)} !important;}`,
          `${classes(false, role)} {background-image:${url(`1_${R}.svg`)} !important;}`,
        ];
      }),
      '',
    ];
    fs.writeFileSync(path.join(cssDestDir, `${set}.css`), css.join('\n'));
    console.log(`Generated taikyokudraft piece css: ${set} (${roles.length} roles)`);
  }
}
